import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools.md","filePath":"reference/tools.md","lastUpdated":1788361435000}`),a={name:`reference/tools.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to “Tools”">​</a></h1><p>All fifty-two are registered unless you say otherwise. <code>MEALIE_ALLOW_TOOLS</code> and <code>MEALIE_DENY_TOOLS</code> narrow the list to the ones you want, and <code>essential</code> selects a curated eight — see <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p><p>One section per tool: what it does, its parameters, and — for the guarded ones — what a person is asked.</p><p>52 tools in total. The 18 read tools are always registered; the 34 write and import tools are omitted when <code>MEALIE_READ_ONLY=true</code>.</p><p>Every tool declares an <code>outputSchema</code> and answers with <code>structuredContent</code> beside the text block, so a client can use a result without parsing prose. Most carry <code>untrusted: true</code> and <code>source: &quot;mealie&quot;</code> as fields of that object — recipes are routinely scraped from arbitrary websites. The ten without the marker answer with an id this server was given, or with <code>get_about</code>’s version and permission flags.</p><div class="info custom-block"><p class="custom-block-title">Recipe references: slug or UUID</p><p>Wherever a parameter is described as a <em>recipe slug or UUID</em>, both work — Mealie splits its identifier space (recipe CRUD uses the slug, meal plans, ratings and timeline events use the UUID), and the tools resolve whichever they are given. Both are returned by <code>search_recipes</code>.</p></div><div class="warning custom-block"><p class="custom-block-title">Tools that ask a person</p><p>Tools marked <strong>Asks a person first</strong> raise a dialog through MCP elicitation, which the model cannot answer on their behalf. Where the client cannot show one they fall back to a two-call flow: call once to receive a <code>confirm_token</code> together with a description of what is about to happen, then call again with the same arguments plus that token. Tokens are single-use, expire after a few minutes, and either way the approval is bound to the specific target. <code>ELICITATION=false</code> takes the fallback deliberately — see <a href="/guide/approval">Asking a person</a>.</p></div><p>Every tool declares all four MCP annotations — <code>readOnlyHint</code>, <code>destructiveHint</code>, <code>idempotentHint</code>, <code>openWorldHint</code>. <code>openWorldHint</code> is <code>true</code> only where Mealie is made to talk to somebody outside itself: <code>import_recipe_from_url</code>, <code>preview_recipe_url</code> and <code>import_recipe_from_image</code>.</p><h2 id="recipes" tabindex="-1">Recipes <a class="header-anchor" href="#recipes" aria-label="Permalink to “Recipes”">​</a></h2><h3 id="search-recipes" tabindex="-1">search_recipes <a class="header-anchor" href="#search-recipes" aria-label="Permalink to “search_recipes”">​</a></h3><p>Searches the recipe collection. Returns summaries — name, slug, id, times, rating, tags and categories — without ingredients or steps; use <code>get_recipe</code> for those. All filters combine with AND; within one filter the entries are OR unless the matching <code>require_all_*</code> flag is set.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>search</code></td><td>string</td><td>no</td><td>Full-text search over names, descriptions and ingredients</td></tr><tr><td><code>tags</code></td><td>string[]</td><td>no</td><td>Restrict to recipes carrying these tags — names, slugs or UUIDs</td></tr><tr><td><code>categories</code></td><td>string[]</td><td>no</td><td>Restrict to recipes carrying these categories</td></tr><tr><td><code>tools</code></td><td>string[]</td><td>no</td><td>Restrict to recipes carrying these tools</td></tr><tr><td><code>foods</code></td><td>string[]</td><td>no</td><td>Restrict to recipes carrying these foods</td></tr><tr><td><code>cookbook</code></td><td>string</td><td>no</td><td>Restrict the result to a cookbook, by slug or UUID</td></tr><tr><td><code>require_all_tags</code></td><td>boolean</td><td>no</td><td>Require every listed tag instead of any of them</td></tr><tr><td><code>require_all_categories</code></td><td>boolean</td><td>no</td><td>Same, for categories</td></tr><tr><td><code>require_all_tools</code></td><td>boolean</td><td>no</td><td>Same, for tools</td></tr><tr><td><code>require_all_foods</code></td><td>boolean</td><td>no</td><td>Same, for foods</td></tr><tr><td><code>order_by</code></td><td>enum</td><td>no</td><td><code>name</code> | <code>rating</code> | <code>created_at</code> | <code>updated_at</code> | <code>last_made</code> | <code>random</code>; default <code>created_at</code></td></tr><tr><td><code>order_direction</code></td><td>enum</td><td>no</td><td><code>asc</code> | <code>desc</code>, default <code>desc</code></td></tr><tr><td><code>page</code></td><td>number</td><td>no</td><td>1-based page number, default 1</td></tr><tr><td><code>per_page</code></td><td>number</td><td>no</td><td>Entries to return, default 25, max 100</td></tr></tbody></table><h3 id="get-recipe" tabindex="-1">get_recipe <a class="header-anchor" href="#get-recipe" aria-label="Permalink to “get_recipe”">​</a></h3><p>Fetches one recipe with everything needed to cook it: ingredients, steps, times, yield, notes and nutrition. Accepts the slug or the UUID.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>recipe</code></td><td>string</td><td>yes</td><td>Recipe slug or UUID</td></tr><tr><td><code>detail</code></td><td>enum</td><td>no</td><td><code>default</code> returns the cleaned-up recipe; <code>raw</code> returns Mealie&#39;s untouched object including settings, assets, extras and inline comments</td></tr></tbody></table><h3 id="suggest-recipes" tabindex="-1">suggest_recipes <a class="header-anchor" href="#suggest-recipes" aria-label="Permalink to “suggest_recipes”">​</a></h3><p>Suggests recipes that can be cooked from the foods and tools marked as &quot;on hand&quot; in Mealie, ranked by how little is missing. This only produces anything on an instance that actually maintains structured foods, units and an on-hand pantry — on a collection of plain-text ingredients it returns nothing; use <code>search_recipes</code> there.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>foods</code></td><td>string[] (UUIDs)</td><td>no</td><td>Food UUIDs to treat as available, from <code>list_foods</code></td></tr><tr><td><code>tools</code></td><td>string[] (UUIDs)</td><td>no</td><td>Tool UUIDs to treat as available, from <code>list_organizers</code></td></tr><tr><td><code>max_missing_foods</code></td><td>number</td><td>no</td><td>How many ingredients a suggestion may be missing, default 5</td></tr><tr><td><code>max_missing_tools</code></td><td>number</td><td>no</td><td>Same, for tools</td></tr><tr><td><code>limit</code></td><td>number</td><td>no</td><td>Number of suggestions, default 10, max 50</td></tr></tbody></table><h3 id="create-recipe" tabindex="-1">create_recipe <a class="header-anchor" href="#create-recipe" aria-label="Permalink to “create_recipe”">​</a></h3><p>Creates a recipe from the given fields. To add one from a website use <code>import_recipe_from_url</code> instead — it fills in far more.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>yes</td><td>Recipe name. Mealie derives the slug from it and rejects a duplicate</td></tr><tr><td><code>description</code></td><td>string</td><td>no</td><td>Recipe description</td></tr><tr><td><code>ingredients</code></td><td>string[]</td><td>no</td><td>Ingredient lines as free text, e.g. <code>&quot;500 g quark&quot;</code>. They replace the existing list; use <code>parse_ingredients</code> first if structured food and unit references are wanted</td></tr><tr><td><code>instructions</code></td><td>string[]</td><td>no</td><td>Preparation steps, in order. They replace the existing list</td></tr><tr><td><code>tags</code></td><td>string[]</td><td>no</td><td>Tag names. They replace the existing tags; unknown names are created</td></tr><tr><td><code>categories</code></td><td>string[]</td><td>no</td><td>Category names. They replace the existing categories</td></tr><tr><td><code>prep_time</code></td><td>string</td><td>no</td><td>Preparation time</td></tr><tr><td><code>cook_time</code></td><td>string</td><td>no</td><td>Cooking time</td></tr><tr><td><code>total_time</code></td><td>string</td><td>no</td><td>Total time</td></tr><tr><td><code>servings</code></td><td>number</td><td>no</td><td>Number of servings</td></tr><tr><td><code>recipe_yield</code></td><td>string</td><td>no</td><td>Yield as text</td></tr><tr><td><code>notes</code></td><td>{ title, text }[]</td><td>no</td><td>Notes attached to the recipe</td></tr><tr><td><code>source_url</code></td><td>string</td><td>no</td><td>Original source of the recipe, stored as <code>orgURL</code></td></tr></tbody></table><h3 id="update-recipe" tabindex="-1">update_recipe <a class="header-anchor" href="#update-recipe" aria-label="Permalink to “update_recipe”">​</a></h3><p>Changes individual fields of a recipe. Only the fields given are touched; everything else keeps its value. Passing an empty array for ingredients, instructions, tags or categories clears that list. Uses <code>PATCH</code> — Mealie&#39;s <code>PUT</code> route, which replaces the whole 33-field object, is deliberately not exposed.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>recipe</code></td><td>string</td><td>yes</td><td>Recipe slug or UUID</td></tr><tr><td><code>name</code></td><td>string</td><td>no</td><td>New recipe name</td></tr><tr><td>…same optional fields as <code>create_recipe</code></td><td></td><td></td><td><code>description</code>, <code>ingredients</code>, <code>instructions</code>, <code>tags</code>, <code>categories</code>, <code>prep_time</code>, <code>cook_time</code>, <code>total_time</code>, <code>servings</code>, <code>recipe_yield</code>, <code>notes</code>, <code>source_url</code></td></tr></tbody></table><h3 id="duplicate-recipe" tabindex="-1">duplicate_recipe <a class="header-anchor" href="#duplicate-recipe" aria-label="Permalink to “duplicate_recipe”">​</a></h3><p>Creates a copy of a recipe under a new name, leaving the original untouched. Useful as a starting point for a variation.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>recipe</code></td><td>string</td><td>yes</td><td>Recipe slug or UUID</td></tr><tr><td><code>name</code></td><td>string</td><td>no</td><td>Name of the copy; Mealie appends a counter when omitted</td></tr></tbody></table><h3 id="set-recipe-last-made" tabindex="-1">set_recipe_last_made <a class="header-anchor" href="#set-recipe-last-made" aria-label="Permalink to “set_recipe_last_made”">​</a></h3><p>Records when a recipe was last cooked. Mealie shows this on the recipe and sorts by it.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>recipe</code></td><td>string</td><td>yes</td><td>Recipe slug or UUID</td></tr><tr><td><code>timestamp</code></td><td>string</td><td>yes</td><td>ISO 8601 date or date-time, e.g. <code>2026-08-18</code> or <code>2026-08-18T19:30:00Z</code></td></tr></tbody></table><h3 id="delete-recipe" tabindex="-1">delete_recipe <a class="header-anchor" href="#delete-recipe" aria-label="Permalink to “delete_recipe”">​</a></h3><p>Deletes a recipe permanently, together with its comments, timeline and images. <strong>Asks a person first.</strong> The token is keyed to the resolved UUID, so a token issued for a slug cannot be replayed against a different recipe that has since taken that slug.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>recipe</code></td><td>string</td><td>yes</td><td>Recipe slug or UUID</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only on the fallback path, where the client cannot show a dialog</td></tr></tbody></table><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to “Import”">​</a></h2><h3 id="preview-recipe-url" tabindex="-1">preview_recipe_url <a class="header-anchor" href="#preview-recipe-url" aria-label="Permalink to “preview_recipe_url”">​</a></h3><p>Fetches a URL and reports what Mealie would extract from it, <strong>without saving anything</strong>. Use this to check a page before importing it, or to find out why an import came out empty.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>url</code></td><td>string</td><td>yes</td><td>Address of the recipe page to test — public <code>http</code>/<code>https</code> only</td></tr></tbody></table><h3 id="import-recipe-from-url" tabindex="-1">import_recipe_from_url <a class="header-anchor" href="#import-recipe-from-url" aria-label="Permalink to “import_recipe_from_url”">​</a></h3><p>Has Mealie fetch a recipe page and save it as a new recipe. The fetch happens on the Mealie server, not here. Everything the page contains — name, description, ingredients, steps — ends up in the collection as written by whoever controls that site.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>url</code></td><td>string</td><td>yes</td><td>Address of the recipe to import — public <code>http</code>/<code>https</code> only</td></tr><tr><td><code>include_tags</code></td><td>boolean</td><td>no</td><td>Adopt the page&#39;s keywords as tags, default false</td></tr><tr><td><code>include_categories</code></td><td>boolean</td><td>no</td><td>Adopt the page&#39;s categories, default false</td></tr></tbody></table><h3 id="import-recipe-from-html-or-json" tabindex="-1">import_recipe_from_html_or_json <a class="header-anchor" href="#import-recipe-from-html-or-json" aria-label="Permalink to “import_recipe_from_html_or_json”">​</a></h3><p>Creates a recipe from HTML or schema.org recipe JSON supplied directly, without Mealie fetching anything. Useful for a page that needs a login, or one that <code>import_recipe_from_url</code> could not parse.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>data</code></td><td>string</td><td>yes</td><td>The page HTML, or a schema.org Recipe JSON document (max 2 MB)</td></tr></tbody></table><h3 id="import-recipe-from-image" tabindex="-1">import_recipe_from_image <a class="header-anchor" href="#import-recipe-from-image" aria-label="Permalink to “import_recipe_from_image”">​</a></h3><p>Creates a recipe from a photo of one — a cookbook page, a handwritten card — by having Mealie run it through its configured AI provider. Requires an AI provider set up in Mealie; without one the call fails, and the setting itself is only visible to a group manager or admin.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>image_base64</code></td><td>string</td><td>yes</td><td>The image, base64-encoded, without a <code>data:</code> URI prefix (max 8 MB)</td></tr><tr><td><code>format</code></td><td>enum</td><td>yes</td><td><code>jpeg</code> | <code>jpg</code> | <code>png</code> | <code>webp</code> — used for the upload filename and content type</td></tr><tr><td><code>translate_language</code></td><td>string</td><td>no</td><td>Translate the extracted recipe into this language, e.g. <code>&quot;de&quot;</code> or <code>&quot;German&quot;</code></td></tr></tbody></table><h2 id="organizing" tabindex="-1">Organizing <a class="header-anchor" href="#organizing" aria-label="Permalink to “Organizing”">​</a></h2><p>Tags, categories and recipe tools share one CRUD shape in Mealie, so each of these tools takes a <code>kind</code> parameter: <code>tag</code> (free-form labels), <code>category</code> (the primary classification, one recipe usually has few) or <code>tool</code> (equipment a recipe needs).</p><h3 id="list-organizers" tabindex="-1">list_organizers <a class="header-anchor" href="#list-organizers" aria-label="Permalink to “list_organizers”">​</a></h3><p>Lists the tags, categories or tools defined in the group, with their ids and slugs. These are the values <code>search_recipes</code> filters on.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>kind</code></td><td>enum</td><td>yes</td><td><code>tag</code> | <code>category</code> | <code>tool</code></td></tr><tr><td><code>search</code></td><td>string</td><td>no</td><td>Filter by name</td></tr><tr><td><code>page</code></td><td>number</td><td>no</td><td>1-based page number, default 1</td></tr><tr><td><code>per_page</code></td><td>number</td><td>no</td><td>Entries to return, default 100, max 100</td></tr><tr><td><code>order_direction</code></td><td>enum</td><td>no</td><td><code>asc</code> | <code>desc</code>, default <code>asc</code></td></tr></tbody></table><h3 id="create-organizer" tabindex="-1">create_organizer <a class="header-anchor" href="#create-organizer" aria-label="Permalink to “create_organizer”">​</a></h3><p>Creates a tag, category or recipe tool. Assigning one to a recipe with <code>update_recipe</code> already creates it on the fly — this tool is for defining one up front.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>kind</code></td><td>enum</td><td>yes</td><td><code>tag</code> | <code>category</code> | <code>tool</code></td></tr><tr><td><code>name</code></td><td>string</td><td>yes</td><td>Name of the new organizer</td></tr></tbody></table><h3 id="update-organizer" tabindex="-1">update_organizer <a class="header-anchor" href="#update-organizer" aria-label="Permalink to “update_organizer”">​</a></h3><p>Renames a tag, category or tool. Mealie regenerates the slug from the new name, so anything referring to the old slug stops matching.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>kind</code></td><td>enum</td><td>yes</td><td><code>tag</code> | <code>category</code> | <code>tool</code></td></tr><tr><td><code>id</code></td><td>string (UUID)</td><td>yes</td><td>UUID from <code>list_organizers</code></td></tr><tr><td><code>name</code></td><td>string</td><td>yes</td><td>The new name</td></tr></tbody></table><h3 id="delete-organizer" tabindex="-1">delete_organizer <a class="header-anchor" href="#delete-organizer" aria-label="Permalink to “delete_organizer”">​</a></h3><p>Deletes a tag, category or tool. The recipes themselves are kept, but they lose the assignment. <strong>Asks a person first.</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>kind</code></td><td>enum</td><td>yes</td><td><code>tag</code> | <code>category</code> | <code>tool</code></td></tr><tr><td><code>id</code></td><td>string (UUID)</td><td>yes</td><td>UUID from <code>list_organizers</code></td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only on the fallback path, where the client cannot show a dialog</td></tr></tbody></table><h2 id="ingredients" tabindex="-1">Ingredients <a class="header-anchor" href="#ingredients" aria-label="Permalink to “Ingredients”">​</a></h2><h3 id="list-foods" tabindex="-1">list_foods <a class="header-anchor" href="#list-foods" aria-label="Permalink to “list_foods”">​</a></h3><p>Lists the structured foods of the group — the ingredient vocabulary Mealie matches ingredient lines against. Many instances leave this empty and keep ingredients as plain text; an empty result means exactly that, not a failure.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>search</code></td><td>string</td><td>no</td><td>Filter by name</td></tr><tr><td><code>page</code></td><td>number</td><td>no</td><td>1-based page number, default 1</td></tr><tr><td><code>per_page</code></td><td>number</td><td>no</td><td>Entries to return, default 100, max 100</td></tr><tr><td><code>order_direction</code></td><td>enum</td><td>no</td><td><code>asc</code> | <code>desc</code>, default <code>asc</code></td></tr></tbody></table><h3 id="create-food" tabindex="-1">create_food <a class="header-anchor" href="#create-food" aria-label="Permalink to “create_food”">​</a></h3><p>Adds a food to the group vocabulary so ingredient lines can be matched against it.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>yes</td><td>Name of the food</td></tr><tr><td><code>plural_name</code></td><td>string</td><td>no</td><td>Plural form</td></tr><tr><td><code>description</code></td><td>string</td><td>no</td><td>Description</td></tr><tr><td><code>label_id</code></td><td>string (UUID)</td><td>no</td><td>Shopping-list label to file this food under</td></tr></tbody></table><h3 id="merge-foods" tabindex="-1">merge_foods <a class="header-anchor" href="#merge-foods" aria-label="Permalink to “merge_foods”">​</a></h3><p>Points every ingredient that uses one food at another one and deletes the source food. <strong>Asks a person first.</strong> The token is bound to the ordered pair — swapping the two arguments would destroy the wrong record, so a token for one direction cannot confirm the other.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>from_id</code></td><td>string (UUID)</td><td>yes</td><td>UUID of the food to merge away — this one is deleted</td></tr><tr><td><code>to_id</code></td><td>string (UUID)</td><td>yes</td><td>UUID of the food to keep — references end up here</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only on the fallback path, where the client cannot show a dialog</td></tr></tbody></table><h3 id="list-units" tabindex="-1">list_units <a class="header-anchor" href="#list-units" aria-label="Permalink to “list_units”">​</a></h3><p>Lists the measurement units of the group, with their abbreviations. Like foods, this is empty on an instance that never seeded them.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>search</code></td><td>string</td><td>no</td><td>Filter by name</td></tr><tr><td><code>page</code></td><td>number</td><td>no</td><td>1-based page number, default 1</td></tr><tr><td><code>per_page</code></td><td>number</td><td>no</td><td>Entries to return, default 100, max 100</td></tr><tr><td><code>order_direction</code></td><td>enum</td><td>no</td><td><code>asc</code> | <code>desc</code>, default <code>asc</code></td></tr></tbody></table><h3 id="create-unit" tabindex="-1">create_unit <a class="header-anchor" href="#create-unit" aria-label="Permalink to “create_unit”">​</a></h3><p>Adds a measurement unit to the group vocabulary.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>yes</td><td>Name of the unit</td></tr><tr><td><code>plural_name</code></td><td>string</td><td>no</td><td>Plural form</td></tr><tr><td><code>abbreviation</code></td><td>string</td><td>no</td><td>Abbreviation, e.g. <code>tbsp</code></td></tr><tr><td><code>use_abbreviation</code></td><td>boolean</td><td>no</td><td>Render the abbreviation instead of the name</td></tr><tr><td><code>fraction</code></td><td>boolean</td><td>no</td><td>Show quantities as fractions (½ cup) rather than decimals</td></tr><tr><td><code>description</code></td><td>string</td><td>no</td><td>Description</td></tr></tbody></table><h3 id="merge-units" tabindex="-1">merge_units <a class="header-anchor" href="#merge-units" aria-label="Permalink to “merge_units”">​</a></h3><p>Points every ingredient that uses one unit at another one and deletes the source unit. <strong>Asks a person first.</strong> As with <code>merge_foods</code>, the token is bound to the merge direction.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>from_id</code></td><td>string (UUID)</td><td>yes</td><td>UUID of the unit to merge away — this one is deleted</td></tr><tr><td><code>to_id</code></td><td>string (UUID)</td><td>yes</td><td>UUID of the unit to keep — references end up here</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only on the fallback path, where the client cannot show a dialog</td></tr></tbody></table><h3 id="parse-ingredients" tabindex="-1">parse_ingredients <a class="header-anchor" href="#parse-ingredients" aria-label="Permalink to “parse_ingredients”">​</a></h3><p>Splits free-text ingredient lines into quantity, unit, food and note, and reports how confident Mealie is about each part. Nothing is saved. Use it to check how a line will be understood before writing it to a recipe or a shopping list.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>ingredients</code></td><td>string[]</td><td>yes</td><td>Ingredient lines, e.g. <code>&quot;2 tbsp olive oil&quot;</code> (1–100 lines)</td></tr><tr><td><code>parser</code></td><td>enum</td><td>no</td><td><code>nlp</code> (default) uses the trained model, <code>brute</code> a rule-based split. Mealie&#39;s <code>openai</code> parser is not exposed — it sends every line to an external provider</td></tr></tbody></table><h2 id="meal-plans" tabindex="-1">Meal plans <a class="header-anchor" href="#meal-plans" aria-label="Permalink to “Meal plans”">​</a></h2><h3 id="list-mealplans" tabindex="-1">list_mealplans <a class="header-anchor" href="#list-mealplans" aria-label="Permalink to “list_mealplans”">​</a></h3><p>Lists the meal plan of the household in a date range. Each entry is either a recipe reference or a free-text note.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>start_date</code></td><td>string</td><td>no</td><td>First day to include, <code>YYYY-MM-DD</code></td></tr><tr><td><code>end_date</code></td><td>string</td><td>no</td><td>Last day to include, <code>YYYY-MM-DD</code></td></tr><tr><td><code>page</code></td><td>number</td><td>no</td><td>1-based page number, default 1</td></tr><tr><td><code>per_page</code></td><td>number</td><td>no</td><td>Entries to return, default 50, max 100</td></tr></tbody></table><h3 id="get-todays-meals" tabindex="-1">get_todays_meals <a class="header-anchor" href="#get-todays-meals" aria-label="Permalink to “get_todays_meals”">​</a></h3><p>Returns the recipes planned for today, as Mealie computes &quot;today&quot; for the household. Answers with a bare list, not a paginated envelope. Takes no parameters.</p><h3 id="create-mealplan-entry" tabindex="-1">create_mealplan_entry <a class="header-anchor" href="#create-mealplan-entry" aria-label="Permalink to “create_mealplan_entry”">​</a></h3><p>Puts a recipe or a free-text note on the meal plan for one day. Give either a recipe or a title, not both — Mealie stores a plan entry as one or the other.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>date</code></td><td>string</td><td>yes</td><td>Day of the meal, <code>YYYY-MM-DD</code></td></tr><tr><td><code>entry_type</code></td><td>enum</td><td>yes</td><td><code>breakfast</code> | <code>lunch</code> | <code>dinner</code> | <code>side</code> | <code>snack</code> | <code>drink</code> | <code>dessert</code></td></tr><tr><td><code>recipe</code></td><td>string</td><td>no*</td><td>Recipe slug or UUID to plan</td></tr><tr><td><code>title</code></td><td>string</td><td>no*</td><td>Free-text entry, for a meal that is not a stored recipe</td></tr><tr><td><code>text</code></td><td>string</td><td>no</td><td>Additional note shown under the title</td></tr></tbody></table><p>* exactly one of <code>recipe</code> or <code>title</code> must be given.</p><h3 id="create-random-meal" tabindex="-1">create_random_meal <a class="header-anchor" href="#create-random-meal" aria-label="Permalink to “create_random_meal”">​</a></h3><p>Lets Mealie pick a recipe for a day and slot, honouring the meal plan rules configured in the household.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>date</code></td><td>string</td><td>yes</td><td>Day of the meal, <code>YYYY-MM-DD</code></td></tr><tr><td><code>entry_type</code></td><td>enum</td><td>yes</td><td><code>breakfast</code> | <code>lunch</code> | <code>dinner</code> | <code>side</code> | <code>snack</code> | <code>drink</code> | <code>dessert</code></td></tr></tbody></table><h3 id="update-mealplan-entry" tabindex="-1">update_mealplan_entry <a class="header-anchor" href="#update-mealplan-entry" aria-label="Permalink to “update_mealplan_entry”">​</a></h3><p>Moves an entry to another day or slot, or replaces the recipe behind it. The current entry is read first and the changes merged onto it, because Mealie&#39;s route is a full-object <code>PUT</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>entry_id</code></td><td>number</td><td>yes</td><td>Plan entry id from <code>list_mealplans</code> — an integer, not a UUID</td></tr><tr><td><code>date</code></td><td>string</td><td>no</td><td>New day, <code>YYYY-MM-DD</code></td></tr><tr><td><code>entry_type</code></td><td>enum</td><td>no</td><td>New slot</td></tr><tr><td><code>recipe</code></td><td>string</td><td>no</td><td>Recipe slug or UUID</td></tr><tr><td><code>title</code></td><td>string</td><td>no</td><td>New title</td></tr><tr><td><code>text</code></td><td>string</td><td>no</td><td>New note</td></tr></tbody></table><h3 id="delete-mealplan-entry" tabindex="-1">delete_mealplan_entry <a class="header-anchor" href="#delete-mealplan-entry" aria-label="Permalink to “delete_mealplan_entry”">​</a></h3><p>Removes one entry from the meal plan. The recipe itself is not touched. <strong>Asks a person first.</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>entry_id</code></td><td>number</td><td>yes</td><td>Plan entry id from <code>list_mealplans</code> — an integer, not a UUID</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only on the fallback path, where the client cannot show a dialog</td></tr></tbody></table><h2 id="shopping" tabindex="-1">Shopping <a class="header-anchor" href="#shopping" aria-label="Permalink to “Shopping”">​</a></h2><h3 id="list-shopping-lists" tabindex="-1">list_shopping_lists <a class="header-anchor" href="#list-shopping-lists" aria-label="Permalink to “list_shopping_lists”">​</a></h3><p>Lists the shopping lists of the household, without their items.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>page</code></td><td>number</td><td>no</td><td>1-based page number, default 1</td></tr><tr><td><code>per_page</code></td><td>number</td><td>no</td><td>Entries to return, default 50, max 100</td></tr></tbody></table><h3 id="get-shopping-list" tabindex="-1">get_shopping_list <a class="header-anchor" href="#get-shopping-list" aria-label="Permalink to “get_shopping_list”">​</a></h3><p>Fetches one shopping list with all of its items, checked and unchecked.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>list_id</code></td><td>string (UUID)</td><td>yes</td><td>Shopping list UUID, from <code>list_shopping_lists</code></td></tr><tr><td><code>include_checked</code></td><td>boolean</td><td>no</td><td>Include items already ticked off, default true</td></tr></tbody></table><h3 id="create-shopping-list" tabindex="-1">create_shopping_list <a class="header-anchor" href="#create-shopping-list" aria-label="Permalink to “create_shopping_list”">​</a></h3><p>Creates an empty shopping list in the household.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>yes</td><td>Name of the new list</td></tr></tbody></table><h3 id="delete-shopping-list" tabindex="-1">delete_shopping_list <a class="header-anchor" href="#delete-shopping-list" aria-label="Permalink to “delete_shopping_list”">​</a></h3><p>Deletes a shopping list and everything on it. <strong>Asks a person first.</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>list_id</code></td><td>string (UUID)</td><td>yes</td><td>Shopping list UUID, from <code>list_shopping_lists</code></td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only on the fallback path, where the client cannot show a dialog</td></tr></tbody></table><h3 id="add-shopping-list-items" tabindex="-1">add_shopping_list_items <a class="header-anchor" href="#add-shopping-list-items" aria-label="Permalink to “add_shopping_list_items”">​</a></h3><p>Adds items to a shopping list as free text (<code>&quot;2 tbsp olive oil&quot;</code>). Mealie does not split these into food and unit automatically — run <code>parse_ingredients</code> first if that matters.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>list_id</code></td><td>string (UUID)</td><td>yes</td><td>Shopping list UUID, from <code>list_shopping_lists</code></td></tr><tr><td><code>items</code></td><td>string[]</td><td>yes</td><td>The lines to add, one item each (1–100)</td></tr></tbody></table><h3 id="update-shopping-list-items" tabindex="-1">update_shopping_list_items <a class="header-anchor" href="#update-shopping-list-items" aria-label="Permalink to “update_shopping_list_items”">​</a></h3><p>Changes items on a shopping list — most often ticking them off. Only the given fields are changed; the rest of each item is preserved (the server reads the list first, because Mealie&#39;s bulk update replaces every field it does not receive). At least one of <code>checked</code>, <code>quantity</code> or <code>note</code> must be given.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>list_id</code></td><td>string (UUID)</td><td>yes</td><td>Shopping list UUID</td></tr><tr><td><code>item_ids</code></td><td>string[] (UUIDs)</td><td>yes</td><td>Item UUIDs from <code>get_shopping_list</code> (1–100)</td></tr><tr><td><code>checked</code></td><td>boolean</td><td>no</td><td>Tick the items off (true) or put them back (false)</td></tr><tr><td><code>quantity</code></td><td>number</td><td>no</td><td>Set the quantity of every listed item</td></tr><tr><td><code>note</code></td><td>string</td><td>no</td><td>Replace the text of every listed item</td></tr></tbody></table><h3 id="delete-shopping-list-items" tabindex="-1">delete_shopping_list_items <a class="header-anchor" href="#delete-shopping-list-items" aria-label="Permalink to “delete_shopping_list_items”">​</a></h3><p>Removes items from a shopping list for good. To merely tick something off, use <code>update_shopping_list_items</code> with <code>checked=true</code>. <strong>Asks a person first.</strong> The approval is bound to a fingerprint of the whole sorted id set, so one for three items cannot delete a fourth appended between the two calls.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>item_ids</code></td><td>string[] (UUIDs)</td><td>yes</td><td>Item UUIDs from <code>get_shopping_list</code> (1–100)</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only on the fallback path, where the client cannot show a dialog</td></tr></tbody></table><h3 id="add-recipe-to-shopping-list" tabindex="-1">add_recipe_to_shopping_list <a class="header-anchor" href="#add-recipe-to-shopping-list" aria-label="Permalink to “add_recipe_to_shopping_list”">​</a></h3><p>Adds a recipe&#39;s ingredients to a shopping list, merging them with what is already there. Mealie remembers the recipe on the list, so <code>remove_recipe_from_shopping_list</code> can take exactly these ingredients back off again.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>list_id</code></td><td>string (UUID)</td><td>yes</td><td>Shopping list UUID</td></tr><tr><td><code>recipe</code></td><td>string</td><td>yes</td><td>Recipe slug or UUID</td></tr><tr><td><code>servings_multiplier</code></td><td>number</td><td>no</td><td>Scale the ingredient quantities, default 1</td></tr></tbody></table><h3 id="remove-recipe-from-shopping-list" tabindex="-1">remove_recipe_from_shopping_list <a class="header-anchor" href="#remove-recipe-from-shopping-list" aria-label="Permalink to “remove_recipe_from_shopping_list”">​</a></h3><p>Takes a recipe&#39;s ingredients back off a shopping list. Items that were also needed by another recipe on the list stay, with their quantity reduced.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>list_id</code></td><td>string (UUID)</td><td>yes</td><td>Shopping list UUID</td></tr><tr><td><code>recipe</code></td><td>string</td><td>yes</td><td>Recipe slug or UUID</td></tr><tr><td><code>servings_multiplier</code></td><td>number</td><td>no</td><td>How much of the recipe to remove, default 1</td></tr></tbody></table><h2 id="cookbooks" tabindex="-1">Cookbooks <a class="header-anchor" href="#cookbooks" aria-label="Permalink to “Cookbooks”">​</a></h2><h3 id="list-cookbooks" tabindex="-1">list_cookbooks <a class="header-anchor" href="#list-cookbooks" aria-label="Permalink to “list_cookbooks”">​</a></h3><p>Lists the cookbooks of the household. A cookbook is a saved filter over the recipe collection, not a fixed set of recipes.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>page</code></td><td>number</td><td>no</td><td>1-based page number, default 1</td></tr><tr><td><code>per_page</code></td><td>number</td><td>no</td><td>Entries to return, default 50, max 100</td></tr></tbody></table><h3 id="get-cookbook" tabindex="-1">get_cookbook <a class="header-anchor" href="#get-cookbook" aria-label="Permalink to “get_cookbook”">​</a></h3><p>Fetches a cookbook and the recipes it currently matches. Accepts the slug or the UUID.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>cookbook</code></td><td>string</td><td>yes</td><td>Cookbook slug or UUID, from <code>list_cookbooks</code></td></tr><tr><td><code>per_page</code></td><td>number</td><td>no</td><td>Recipes to return, default 50, max 100</td></tr></tbody></table><h3 id="create-cookbook" tabindex="-1">create_cookbook <a class="header-anchor" href="#create-cookbook" aria-label="Permalink to “create_cookbook”">​</a></h3><p>Creates a cookbook — a named, saved view of the recipe collection. Without a filter it matches every recipe; the filter itself is written in Mealie&#39;s own query language and is easiest to build in the web UI.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>yes</td><td>Name of the cookbook</td></tr><tr><td><code>description</code></td><td>string</td><td>no</td><td>Description</td></tr><tr><td><code>query_filter</code></td><td>string</td><td>no</td><td>Mealie query filter, e.g. <code>tags.name IN [&quot;Dessert&quot;]</code>. Passed through verbatim; an invalid expression is rejected by Mealie with a 422</td></tr><tr><td><code>is_public</code></td><td>boolean</td><td>no</td><td>Make the cookbook readable without a login, default false</td></tr></tbody></table><h3 id="delete-cookbook" tabindex="-1">delete_cookbook <a class="header-anchor" href="#delete-cookbook" aria-label="Permalink to “delete_cookbook”">​</a></h3><p>Deletes a cookbook. The recipes it matched are not touched — a cookbook is only a saved filter. <strong>Asks a person first.</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>cookbook_id</code></td><td>string (UUID)</td><td>yes</td><td>Cookbook UUID, from <code>list_cookbooks</code></td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only on the fallback path, where the client cannot show a dialog</td></tr></tbody></table><h2 id="notes-sharing" tabindex="-1">Notes &amp; sharing <a class="header-anchor" href="#notes-sharing" aria-label="Permalink to “Notes &amp; sharing”">​</a></h2><h3 id="set-recipe-rating" tabindex="-1">set_recipe_rating <a class="header-anchor" href="#set-recipe-rating" aria-label="Permalink to “set_recipe_rating”">​</a></h3><p>Sets the personal rating of a recipe and/or marks it as a favourite. Ratings in Mealie are per user, not per recipe. At least one of <code>rating</code> or <code>is_favorite</code> must be given.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>recipe</code></td><td>string</td><td>yes</td><td>Recipe slug or UUID</td></tr><tr><td><code>rating</code></td><td>number</td><td>no</td><td>Stars from 0 to 5; 0 clears the rating</td></tr><tr><td><code>is_favorite</code></td><td>boolean</td><td>no</td><td>Mark or unmark as a favourite</td></tr></tbody></table><h3 id="add-recipe-comment" tabindex="-1">add_recipe_comment <a class="header-anchor" href="#add-recipe-comment" aria-label="Permalink to “add_recipe_comment”">​</a></h3><p>Adds a comment to a recipe. Comments are visible to everyone in the group and are attributed to the user the API token belongs to.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>recipe</code></td><td>string</td><td>yes</td><td>Recipe slug or UUID</td></tr><tr><td><code>text</code></td><td>string</td><td>yes</td><td>The comment text</td></tr></tbody></table><h3 id="delete-recipe-comment" tabindex="-1">delete_recipe_comment <a class="header-anchor" href="#delete-recipe-comment" aria-label="Permalink to “delete_recipe_comment”">​</a></h3><p>Deletes a comment. <strong>Asks a person first.</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>comment_id</code></td><td>string (UUID)</td><td>yes</td><td>Comment UUID, from <code>list_recipe_comments</code></td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only on the fallback path, where the client cannot show a dialog</td></tr></tbody></table><h3 id="list-recipe-comments" tabindex="-1">list_recipe_comments <a class="header-anchor" href="#list-recipe-comments" aria-label="Permalink to “list_recipe_comments”">​</a></h3><p>Lists the comments other users of the instance left on a recipe.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>recipe</code></td><td>string</td><td>yes</td><td>Recipe slug or UUID</td></tr></tbody></table><h3 id="list-recipe-timeline" tabindex="-1">list_recipe_timeline <a class="header-anchor" href="#list-recipe-timeline" aria-label="Permalink to “list_recipe_timeline”">​</a></h3><p>Lists the timeline of a recipe: when it was created, updated and each time it was cooked, with the notes attached to those events.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>recipe</code></td><td>string</td><td>yes</td><td>Recipe slug or UUID</td></tr><tr><td><code>page</code></td><td>number</td><td>no</td><td>1-based page number, default 1</td></tr><tr><td><code>per_page</code></td><td>number</td><td>no</td><td>Entries to return, default 50, max 100</td></tr></tbody></table><h3 id="create-timeline-event" tabindex="-1">create_timeline_event <a class="header-anchor" href="#create-timeline-event" aria-label="Permalink to “create_timeline_event”">​</a></h3><p>Adds an entry to a recipe&#39;s timeline — typically a note about having cooked it and how it turned out. Pair it with <code>set_recipe_last_made</code>, which is what the recipe view sorts on.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>recipe</code></td><td>string</td><td>yes</td><td>Recipe slug or UUID</td></tr><tr><td><code>subject</code></td><td>string</td><td>yes</td><td>Short headline, e.g. <code>&quot;Cooked it&quot;</code></td></tr><tr><td><code>message</code></td><td>string</td><td>no</td><td>The note itself</td></tr><tr><td><code>timestamp</code></td><td>string</td><td>no</td><td>ISO 8601 date or date-time; defaults to now</td></tr></tbody></table><h3 id="list-share-tokens" tabindex="-1">list_share_tokens <a class="header-anchor" href="#list-share-tokens" aria-label="Permalink to “list_share_tokens”">​</a></h3><p>Lists the public share links that currently exist, with the recipe each one exposes and when it expires. Anyone holding such a link can read the recipe without an account.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>recipe</code></td><td>string</td><td>no</td><td>Restrict the result to one recipe (slug or UUID)</td></tr></tbody></table><h3 id="create-share-token" tabindex="-1">create_share_token <a class="header-anchor" href="#create-share-token" aria-label="Permalink to “create_share_token”">​</a></h3><p>Creates a link that lets anyone read one recipe without logging in. <strong>Requires a confirmation token: call once to receive one, call again with it</strong> — guarded like a destructive operation even though it destroys nothing, because it is the one tool that widens who can see the data.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>recipe</code></td><td>string</td><td>yes</td><td>Recipe slug or UUID</td></tr><tr><td><code>expires_at</code></td><td>string</td><td>no</td><td>ISO 8601 date or date-time when the link stops working. Omitted, it never expires — prefer setting a date</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only on the fallback path, where the client cannot show a dialog</td></tr></tbody></table><h3 id="delete-share-token" tabindex="-1">delete_share_token <a class="header-anchor" href="#delete-share-token" aria-label="Permalink to “delete_share_token”">​</a></h3><p>Revokes a share link, so the recipe is no longer readable through it. <strong>Asks a person first.</strong></p><p>It used to say it needed no confirmation, on the grounds that revoking narrows access rather than widening it. The direction is the safe one; what is not is that the link cannot be reissued — a new share token is a different URL, so whoever was sent the old one finds a dead link, and this server cannot tell whom that was.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>token_id</code></td><td>string (UUID)</td><td>yes</td><td>Share token UUID, from <code>list_share_tokens</code></td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only on the fallback path, where the client cannot show a dialog</td></tr></tbody></table><h2 id="instance" tabindex="-1">Instance <a class="header-anchor" href="#instance" aria-label="Permalink to “Instance”">​</a></h2><h3 id="get-about" tabindex="-1">get_about <a class="header-anchor" href="#get-about" aria-label="Permalink to “get_about”">​</a></h3><p>Reports the Mealie version and the identity the API token acts as: user, group, household and the permission flags that decide which write tools will actually succeed. Start here when a call fails with a 403. Takes no parameters.</p>`,174)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};